def process(floridaFraudOther, metroFraudOther2024) -> pd.DataFrame:
    import pandas as pd
    import re

    def norm(s: str) -> str:
        if s is None:
            return ""
        s = str(s).strip().lower()
        s = re.sub(r"\s+", " ", s)
        return s

    target = norm("Miami-Fort Lauderdale-West Palm Beach")

    # Find likely name columns
    def find_col(df, patterns):
        cols = list(df.columns)
        for p in patterns:
            for c in cols:
                if re.search(p, c, flags=re.I):
                    return c
        return None

    nameColFl = find_col(floridaFraudOther, [r"msa", r"metropolitan", r"area", r"geography", r"name"])
    nameColMetro = find_col(metroFraudOther2024, [r"msa", r"metropolitan", r"area", r"geography", r"name"])

    # Find likely report-count column(s)
    def find_count_cols(df):
        cands = []
        for c in df.columns:
            if re.search(r"report", c, flags=re.I) or re.search(r"count", c, flags=re.I) or re.search(r"complaint", c, flags=re.I):
                cands.append(c)
        return cands

    countColsFl = find_count_cols(floridaFraudOther)
    countColsMetro = find_count_cols(metroFraudOther2024)

    # Fallback: numeric-looking columns if none matched
    if not countColsFl:
        countColsFl = list(floridaFraudOther.columns)
    if not countColsMetro:
        countColsMetro = list(metroFraudOther2024.columns)

    # Filter rows matching target in name column (if present)
    fl = floridaFraudOther.copy()
    metro = metroFraudOther2024.copy()

    if nameColFl:
        fl = fl[fl[nameColFl].astype(str).map(norm).str.contains(target, na=False)]
    else:
        # search across all columns
        fl = fl[fl.astype(str).apply(lambda r: any(target in norm(v) for v in r), axis=1)]

    if nameColMetro:
        metro = metro[metro[nameColMetro].astype(str).map(norm).str.contains(target, na=False)]
    else:
        metro = metro[metro.astype(str).apply(lambda r: any(target in norm(v) for v in r), axis=1)]

    # Determine year columns if any
    def infer_year_col(df):
        for c in df.columns:
            if re.fullmatch(r"20\d{2}", str(c).strip()):
                return None  # wide format, years as columns
        for c in df.columns:
            if re.search(r"year", c, flags=re.I):
                return c
        return None

    yearColFl = infer_year_col(fl)
    yearColMetro = infer_year_col(metro)

    # Extract 2024 report count values from each dataset
    def to_num(x):
        if pd.isna(x):
            return None
        s = str(x)
        s = re.sub(r"[^0-9.\-]", "", s)
        if s == "":
            return None
        try:
            return float(s)
        except Exception:
            return None

    def extract_2024(df, countCols, yearCol):
        if df.shape[0] == 0:
            return []
        if yearCol and yearCol in df.columns:
            d2 = df[df[yearCol].astype(str).str.strip() == "2024"]
            vals = []
            for c in countCols:
                if c in d2.columns:
                    vals += [to_num(v) for v in d2[c].tolist()]
            return [v for v in vals if v is not None]

        # wide year columns
        if "2024" in [str(c).strip() for c in df.columns]:
            col2024 = [c for c in df.columns if str(c).strip() == "2024"][0]
            vals = [to_num(v) for v in df[col2024].tolist()]
            return [v for v in vals if v is not None]

        # If no explicit year, assume already 2024 (file is 2024 data)
        vals = []
        for c in countCols:
            if c in df.columns:
                vals += [to_num(v) for v in df[c].tolist()]
        return [v for v in vals if v is not None]

    valsFl = extract_2024(fl, countColsFl, yearColFl)
    valsMetro = extract_2024(metro, countColsMetro, yearColMetro)

    # Heuristic: choose a single representative count by taking max (report totals often max among measures)
    repFl = max(valsFl) if valsFl else None
    repMetro = max(valsMetro) if valsMetro else None

    consistent = (repFl is not None) and (repMetro is not None) and (abs(repFl - repMetro) < 1e-9)

    return pd.DataFrame([{
        "repCountFloridaFraudOther": repFl,
        "repCountMetroFraudOther2024": repMetro,
        "consistent": bool(consistent),
        "matchedRowsFlorida": int(fl.shape[0]),
        "matchedRowsMetro": int(metro.shape[0])
    }])

def load() -> pd.DataFrame:
    import pandas as pd
    path = "data/legal/input/csn-data-book-2024-csv/CSVs/2024_CSN_Metropolitan_Areas_Fraud_and_Other_Reports.csv"
    # File contains non-UTF8 characters; try Windows-1252 then Latin-1 as common fallbacks
    try:
        return pd.read_csv(path, dtype=str, encoding="cp1252")
    except UnicodeDecodeError:
        return pd.read_csv(path, dtype=str, encoding="latin1")

def process(floridaFraudOther, metroFraudOther2024) -> pd.DataFrame:
    import pandas as pd
    import re

    def norm(s: str) -> str:
        s = str(s) if s is not None else ""
        s = s.lower().strip()
        s = re.sub(r"\s+", " ", s)
        s = s.replace("-", " ")
        s = re.sub(r"[^a-z0-9 ]", "", s)
        s = re.sub(r"\s+", " ", s).strip()
        return s

    def to_num(x):
        if x is None or (isinstance(x, float) and pd.isna(x)):
            return None
        s = str(x).strip()
        if s == "" or s.lower() in {"nan", "na", "n/a"}:
            return None
        s = re.sub(r"[^0-9\.-]", "", s)
        if s in {"", ".", "-"}:
            return None
        try:
            return float(s)
        except Exception:
            return None

    target = norm("Miami-Fort Lauderdale-West Palm Beach")

    def find_row(df: pd.DataFrame, candidate_cols):
        for c in candidate_cols:
            if c in df.columns:
                m = df[c].astype(str).map(norm).str.contains(target, na=False)
                if m.any():
                    return df[m].copy(), c
        return df.iloc[0:0].copy(), None

    # --- Florida fraud/other table ---
    fl = floridaFraudOther.copy()
    fl_cols = list(fl.columns)
    fl_match, fl_col = find_row(fl, [
        "Metropolitan Areas: Fraud and Other Reports",
        "Metropolitan Area",
        fl_cols[0] if fl_cols else ""
    ])

    # Try to pick report count column
    fl_count_cols = [c for c in fl_match.columns if re.search(r"# of reports|reports$|number of reports", str(c), flags=re.I)]
    # also unnamed numeric col likely second column
    if not fl_count_cols and fl_cols:
        if len(fl_cols) >= 2:
            fl_count_cols = [fl_cols[1]]
        elif len(fl_cols) == 1:
            fl_count_cols = [fl_cols[0]]

    fl_val = None
    if len(fl_match) > 0 and fl_count_cols:
        nums = []
        for c in fl_count_cols:
            nums.extend([to_num(v) for v in fl_match[c].tolist()])
        nums = [n for n in nums if n is not None]
        if nums:
            fl_val = max(nums)

    # --- Metro fraud/other 2024 table ---
    metro = metroFraudOther2024.copy()
    metro_cols = list(metro.columns)
    metro_match, metro_col = find_row(metro, [
        "Metropolitan Area",
        "Unnamed: 1",
        "Metropolitan Areas: Fraud and Other Reports"
    ])

    # likely count is '# of Reports' which appears as a data row in row 1; actual column is Unnamed: 3
    metro_count_candidates = []
    # detect by scanning row 1 header-like content
    if len(metro) >= 2:
        header_like = metro.iloc[1].astype(str).tolist()
        for j, cell in enumerate(header_like):
            if re.search(r"#\s*of\s*reports", cell, flags=re.I):
                metro_count_candidates.append(metro.columns[j])
    if not metro_count_candidates:
        # fallback to common unnamed col
        for c in ["Unnamed: 3", "# of Reports"]:
            if c in metro.columns:
                metro_count_candidates.append(c)
    if not metro_count_candidates and metro_cols:
        metro_count_candidates = [metro_cols[-1]]

    metro_val = None
    if len(metro_match) > 0 and metro_count_candidates:
        nums = []
        for c in metro_count_candidates:
            if c in metro_match.columns:
                nums.extend([to_num(v) for v in metro_match[c].tolist()])
        nums = [n for n in nums if n is not None]
        if nums:
            metro_val = max(nums)

    consistent = (fl_val is not None) and (metro_val is not None) and (abs(fl_val - metro_val) < 1e-9)

    return pd.DataFrame([{
        "repCountFloridaFraudOther": None if fl_val is None else int(fl_val) if float(fl_val).is_integer() else fl_val,
        "repCountMetroFraudOther2024": None if metro_val is None else int(metro_val) if float(metro_val).is_integer() else metro_val,
        "consistent": bool(consistent),
        "matchedRowsFlorida": int(len(fl_match)),
        "matchedRowsMetro": int(len(metro_match)),
        "matchedColFlorida": fl_col,
        "matchedColMetro": metro_col,
        "metroCountColsUsed": ",".join(metro_count_candidates) if metro_count_candidates else None,
        "flCountColsUsed": ",".join(fl_count_cols) if fl_count_cols else None,
    }])

